sparql:
PREFIX hlo: <http://example.org/hlo.owl#>
PREFIX ext: <https://example.org/hlo-research/>
SELECT DISTINCT ?resource WHERE {
  VALUES ?skillClass { <http://example.org/hlo.owl#K003> }
  ?resource a hlo:LearningResource ;
    hlo:supportsObjective ?objective ;
    hlo:recommendedFor ?level ; ext:estimatedDurationMinutes ?duration .
  ?objective hlo:requiresCompetency ?competency .
  ?competency hlo:developsSkill ?skill .
  ?skill a ?skillClass .
  ?level a hlo:Fellow .
  FILTER (?duration <= 30)
} ORDER BY ?resource

